          <div
            style={{
              height: 70,
              display: "flex",
              alignItems: "center",
              padding: "0 26px",
              gap: 12,
              borderBottom: "1.5px solid rgba(255,255,255,0.07)",
            }}
          >
            {["#ff5f57", "#febc2e", "#28c840"].map((c) => (
              <span key={c} style={{ width: 16, height: 16, borderRadius: 99, background: c }} />
