            <span style={{ marginLeft: 18, fontSize: 24, color: "#8a8f98" }}>claude</span>
            <span
              style={{
                marginLeft: "auto",
                display: "flex",
                alignItems: "center",
                gap: 10,
                fontSize: 22,
                color: C.flareSoft,
                background: "rgba(255,51,0,0.12)",
