          alignItems: "center",
          gap: 16,
          background: C.ink,
          color: C.white,
          fontSize: 34,
          fontWeight: 500,
          padding: "18px 34px 18px 22px",
          borderRadius: 999,
          transform: `scale(${done})`,
          opacity: settled ? 1 : 0,
        }}
      >
        <Check size={40} />
        Done. Ready in 8 minutes.
      </div>
    </AbsoluteFill>
  );
};

