args.command:
mkdir -p /tmp/lumail/verify && cd /tmp/lumail/verify && printf '{"name":"verify","private":true}\n' > package.json && pnpm add playwright-core 2>&1 | tail -1 && cat > check.mjs <<'EOF'
import { chromium } from "playwright-core";
const url = "file://" + process.argv[2] + "/index.html";
const browser = await chromium.launch({ channel: "chrome", args: ["--autoplay-policy=no-user-gesture-required"] });
for (const vp of [{ width: 1600, height: 1000 }, { width: 900, height: 1400 }]) {
  const page = await browser.newPage({ viewport: vp });
  await page.goto(url);
  await page.waitForFunction(() => document.querySelector("video").readyState >= 3);
  const r = await page.evaluate(async () => {
    const v = document.querySelector("video");
    v.muted = true;
    await v.play();
    await new Promise((res) => setTimeout(res, 2500));
    const b = v.getBoundingClientRect();
    return {
      title: document.title, h1: document.querySelectorAll("h1,h2").length, controls: v.controls,
      duration: v.duration, videoW: v.videoWidth, videoH: v.videoHeight,
      currentTime: +v.currentTime.toFixed(2), paused: v.paused, error: v.error && v.error.code,
      box: [b.left, b.top, b.width, b.height].map(Math.round), ratio: +(b.width / b.height).toFixed(4),
    };
  });
  console.log(JSON.stringify({ viewport: vp, ...r }));
  await page.screenshot({ path: `/tmp/lumail/stills/player_${vp.width}.png` });
  await page.close();
}
await browser.close();
EOF
